module.exports = async (args) => {
  const fs = require('fs');
  const file = args.inputFileObj._id;
  const nlink = fs.statSync(file).nlink;
  const remux = /remux/i.test(file);
  args.jobLog(`links=${nlink} remux=${remux}`);
  // A second link means a seeding torrent shares this inode; re-encoding would split it into two copies.
  const skip = nlink > 1 || remux;
  return { outputFileObj: args.inputFileObj, outputNumber: skip ? 2 : 1, variables: args.variables };
};

module.exports = async (args) => {
  const { spawnSync } = require('child_process');
  const path = require('path');
  const file = args.inputFileObj;
  const pass = { outputFileObj: file, outputNumber: 1, variables: args.variables };
  if (path.extname(file._id).toLowerCase() !== '.mkv') return pass;
  const audio = file.ffProbeData.streams.filter((s) => s.codec_type === 'audio');
  // Commentary and audio-description tracks are often tagged eng; they must not become the default.
  const usable = (s) => {
    const d = s.disposition || {};
    const title = ((s.tags && s.tags.title) || '').toLowerCase();
    return !d.comment && !d.visual_impaired && !/commentary|descriptive|description/.test(title);
  };
  const isEnglish = (s) => ['eng', 'en'].includes(((s.tags && s.tags.language) || '').toLowerCase());
  const target = audio.findIndex((s) => isEnglish(s) && usable(s));
  const defaults = audio.flatMap((s, i) => ((s.disposition || {}).default ? [i] : []));
  if (target < 0 || (target === 0 && defaults.length === 1 && defaults[0] === 0)) return pass;
  const others = audio.map((_, i) => i).filter((i) => i !== target);
  // A default subtitle in another language would show on screen over the English audio.
  const subs = file.ffProbeData.streams.filter((s) => s.codec_type === 'subtitle');
  const clearSubs = subs.flatMap((s, i) => ((s.disposition || {}).default && !isEnglish(s) ? [`-disposition:s:${i}`, '-default'] : []));
  const out = path.join(args.workDir, `${path.parse(file._id).name}.mkv`);
  const cmd = ['-y', '-nostdin', '-v', 'error', '-i', file._id, '-map', '0:v', '-map', `0:a:${target}`,
    ...others.flatMap((i) => ['-map', `0:a:${i}`]),
    '-map', '0:s?', '-map', '0:d?', '-map', '0:t?', '-c', 'copy', '-map_metadata', '0', '-map_chapters', '0',
    '-disposition:a:0', '+default',
    ...others.flatMap((_, i) => [`-disposition:a:${i + 1}`, '-default']), ...clearSubs, out];
  args.jobLog(`english audio ${target} moved to first`);
  const run = spawnSync(args.ffmpegPath, cmd, { encoding: 'utf8' });
  if (run.status !== 0) throw new Error(`ffmpeg failed: ${run.stderr}`);
  return { outputFileObj: { _id: out }, outputNumber: 2, variables: args.variables };
};
